using System;using System.IO;using System.Linq;using System.Text;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine;using UnityEngine.SceneManagement;
public static class UniqueClassroomDoodles {
 const string Root="Assets/StudyImmersive/Art/KIT/UniqueBoards/";
 [InitializeOnLoadMethod]static void Init(){if(File.Exists("Library/unique-classroom-doodles.request"))EditorApplication.delayCall+=Run;}
 static void Check(bool ok,string message){if(!ok)throw new Exception(message);}
 static void Run(){if(!File.Exists("Library/unique-classroom-doodles.request"))return;File.Delete("Library/unique-classroom-doodles.request");try{
  var scene=SceneManager.GetActiveScene();Check(!EditorApplication.isPlayingOrWillChangePlaymode&&scene.path=="Assets/StudyImmersive/Scenes/GrandLibrary_Living.unity","Open the original scene in Edit mode");
  var boards=scene.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<Transform>(true)).Where(t=>t.name.StartsWith("Classroom Doodle Board ")).OrderBy(t=>t.name).ToArray();Check(boards.Length==5,"Expected five existing boards, got "+boards.Length);
  var positions=boards.Select(t=>t.localPosition).ToArray();var rotations=boards.Select(t=>t.localRotation).ToArray();var scales=boards.Select(t=>t.localScale).ToArray();var parents=boards.Select(t=>t.parent).ToArray();var info=new StringBuilder();
  for(int i=0;i<boards.Length;i++){string texPath=Root+"Board_"+(i+1).ToString("00")+".png";AssetDatabase.ImportAsset(texPath,ImportAssetOptions.ForceSynchronousImport);var tex=AssetDatabase.LoadAssetAtPath<Texture2D>(texPath);Check(tex,"Missing drawing "+texPath);string materialPath=Root+"Board_"+(i+1).ToString("00")+".mat";var mat=AssetDatabase.LoadAssetAtPath<Material>(materialPath);if(!mat){mat=new Material(Shader.Find("Unlit/Texture"));AssetDatabase.CreateAsset(mat,materialPath);}mat.mainTexture=tex;EditorUtility.SetDirty(mat);var renderer=boards[i].GetComponent<Renderer>();Check(renderer,"Board has no renderer: "+boards[i].name);Undo.RecordObject(renderer,"Assign unique whiteboard drawing");renderer.sharedMaterial=mat;
   Check(boards[i].localPosition==positions[i]&&boards[i].localRotation==rotations[i]&&boards[i].localScale==scales[i]&&boards[i].parent==parents[i],"User transform changed: "+boards[i].name);info.AppendLine(boards[i].name+" position="+positions[i].ToString("F3")+" scale="+scales[i].ToString("F3")+" drawing="+tex.name);}
  Check(boards.Select(b=>b.GetComponent<Renderer>().sharedMaterial.mainTexture).Distinct().Count()==5,"Duplicate drawings");EditorSceneManager.MarkSceneDirty(scene);Check(EditorSceneManager.SaveScene(scene),"Scene save failed");AssetDatabase.SaveAssets();File.WriteAllText("Tools/unique-doodle-result.txt","PASS\nuniqueBoards=5\ntransformsPreserved=5\n"+info);Debug.Log("UNIQUE_CLASSROOM_DOODLES_PASS five unique boards and preserved transforms");
 }catch(Exception e){File.WriteAllText("Tools/unique-doodle-result.txt","FAIL "+e);Debug.LogException(e);}}
}
